-- Independent adversarial rollback checks against the retained fictional race fixture.
begin;
select set_config('request.jwt.claim.role','service_role',true);
do $$
declare
 org uuid:='92000000-0000-4000-a000-000000000001'; v_manager_id uuid; v_lead_id uuid; v_second_id uuid:=gen_random_uuid();
 v_person_id text; v_learner_id text; v_plan_id uuid; a jsonb; replay jsonb; cmd jsonb; data jsonb; counts_before jsonb; old_email text;
begin
 select id into strict v_manager_id from public.levytate_users where organisation_id=org and role='Line Manager' and active;
 select id into strict v_lead_id from public.levytate_users where organisation_id=org and role='Apprenticeship Lead' and active;
 select e.id into strict v_person_id from public.levytate_employees e join public.levytate_users u on u.organisation_id=e.organisation_id and lower(u.email)=lower(e.email) where u.id=v_manager_id and e.status='Active';
 select l.id,p.current_published_version_id into strict v_learner_id,v_plan_id from public.levytate_learner_records l join public.levytate_otj_plans p on p.organisation_id=l.organisation_id and p.learner_record_id=l.id where l.organisation_id=org and l.employee_id=v_person_id;
 data:=jsonb_build_object('plan_version_id',v_plan_id,'activity_date',current_date-2,'started_at','15:00','ended_at','16:00','break_minutes',0,'duration_minutes',60,'timezone','Europe/London','category','provider_workshop','title','Independent rollback learning evidence','description','Fictional only','what_was_new','New synthetic method','standard_relevance','Fictional standard','reflection','No customer information','working_hours_basis','within_normal_working_hours','compensation_note','','separate_from_productive_work',true,'ksb_references','[]'::jsonb,'evidence_reference','independent-local','deterministic_outcome','likely_eligible','deterministic_reasons','[]'::jsonb);
 cmd:=jsonb_build_object('idempotencyKey','independent-manager-draft','learnerRecordId',v_learner_id);
 a:=public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd,data);
 if a->>'status'<>'draft' or a->>'created_by_user_id'<>v_manager_id::text then raise exception 'Own manager draft not created';end if;
 select jsonb_build_array((select count(*) from public.levytate_otj_activities where organisation_id=org),(select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) into counts_before;
 replay:=public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd,data);
 if replay<>a or counts_before<>jsonb_build_array((select count(*) from public.levytate_otj_activities where organisation_id=org),(select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) then raise exception 'Retry duplicated evidence';end if;
 raise notice 'PASS own Manager evidence and exact receipt are atomic';
 update public.levytate_employees set status='Archived' where organisation_id=org and id=v_person_id;
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd,'{}',true);raise exception 'Archived identity receipt leaked';exception when sqlstate 'PT403' then null;end;
 update public.levytate_employees set status='Active' where organisation_id=org and id=v_person_id;
 select email into old_email from public.levytate_users where id=v_manager_id;
 update public.levytate_users set email='independent-reassigned@example.invalid' where id=v_manager_id;
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd,'{}',true);raise exception 'Reassigned identity receipt leaked';exception when sqlstate 'PT403' then null;end;
 update public.levytate_users set email=old_email,role='Department Head' where id=v_manager_id;
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd,'{}',true);raise exception 'Changed role receipt leaked';exception when sqlstate 'PT403' then null;end;
 update public.levytate_users set role='Line Manager' where id=v_manager_id;
 raise notice 'PASS current People identity and role are rechecked before receipt';
 a:=public.levytate_apply_learning_time_command(org,v_manager_id,'submit_activity',jsonb_build_object('idempotencyKey','independent-manager-submit','activityId',a->>'id','lockVersion',0));
 if a->>'status'<>'submitted' then raise exception 'Own manager submit failed';end if;
 raise notice 'PASS genuine wrapper accepts own Manager submit';
 select jsonb_build_array((select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) into counts_before;
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'transition_activity',jsonb_build_object('idempotencyKey','independent-self-check','activityId',a->>'id','lockVersion',1,'action','employer_check','note','Independent forbidden check'));raise exception 'Self-check allowed';exception when sqlstate 'PT403' then null;end;
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'record_confirmation',jsonb_build_object('idempotencyKey','independent-self-confirm','activityId',a->>'id'));raise exception 'Self-confirmation allowed';exception when sqlstate 'PT403' then null;end;
 if counts_before<>jsonb_build_array((select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) or (select status from public.levytate_otj_activities where id=(a->>'id')::uuid)<>'submitted' then raise exception 'Denied self-review left effects';end if;
 raise notice 'PASS self-review and confirmation denied without audit receipt or activity change';
 cmd:=jsonb_build_object('idempotencyKey','independent-shared-event','activityId',a->>'id','lockVersion',1,'action','employer_check','note','Independent real employer check');
 a:=public.levytate_apply_learning_time_command(org,v_lead_id,'transition_activity',cmd);
 if a->>'status'<>'employer_checked' then raise exception 'Employer oversight failed';end if;
 insert into public.levytate_users(id,organisation_id,email,role,access_level,active)values(v_second_id,org,'independent-reviewer@example.invalid','Employer Admin','Employer',true);
 select jsonb_build_array((select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) into counts_before;
 begin perform public.levytate_apply_learning_time_command(org,v_second_id,'transition_activity',cmd);raise exception 'Other actor event key falsely confirmed';exception when sqlstate 'PT409' then null;end;
 if counts_before<>jsonb_build_array((select count(*) from public.levytate_otj_activity_events where organisation_id=org),(select count(*) from public.levytate_otj_command_receipts where organisation_id=org),(select count(*) from public.levytate_audit_events where organisation_id=org)) then raise exception 'False review left durable effects';end if;
 raise notice 'PASS legacy cross-actor event key cannot manufacture confirmation or audit';
 if not has_function_privilege('service_role','public.levytate_apply_learning_time_command(uuid,uuid,text,jsonb,jsonb,boolean)','execute') or has_function_privilege('authenticated','public.levytate_apply_learning_time_command(uuid,uuid,text,jsonb,jsonb,boolean)','execute') or has_function_privilege('anon','public.levytate_apply_learning_time_command(uuid,uuid,text,jsonb,jsonb,boolean)','execute') then raise exception 'Wrapper grants incorrect';end if;
 if has_function_privilege('service_role','public.levytate_submit_otj_activity(uuid,uuid,uuid,text,integer)','execute') or has_function_privilege('service_role','public.levytate_transition_otj_activity(uuid,uuid,uuid,text,text,text,integer)','execute') or has_table_privilege('service_role','public.levytate_otj_activities','INSERT,UPDATE,DELETE') then raise exception 'Nested direct write entrypoint available';end if;
 raise notice 'PASS effective service browser and nested grants remain closed';
 execute 'set local role service_role';
 begin perform public.levytate_submit_otj_activity(org,(a->>'id')::uuid,v_manager_id,'independent-direct-inner',2);raise exception 'Direct inner execute succeeded';exception when insufficient_privilege then null;end;
 execute 'reset role';
 raise notice 'PASS actual service_role cannot invoke legacy inner submission directly';
 execute 'set local role authenticated';
 begin perform public.levytate_apply_learning_time_command(org,v_manager_id,'save_activity',cmd);raise exception 'Browser wrapper execute succeeded';exception when insufficient_privilege then null;end;
 execute 'reset role';
 raise notice 'PASS actual authenticated role cannot invoke the privileged wrapper';
end $$;
rollback;
